#include <aibs/warm_opening.hpp>
#include <aibs/companion_runtime.hpp>
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace aibs;
unsigned checks=0;void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
int main(){try{
 CreatorSession source(first_boot_schema(),"opening-main-clearance","test");check(seed_first_boot(source).ok,"Seed");const auto definition=make_warm_opening_definition(source,{});const auto content=FirstBootContent::create(definition);const auto baseline=first_boot_content_baseline(content);const GameplayScope scope{"opening-main-clearance",definition.world_id,"test",new_uuid(),GameplayContext::temporary_play};
 auto state=[&](bool main,bool service){GameplayStoreRecovery out{scope,0,0,baseline.components};for(auto& row:out.components)if(row.type_id=="firstboot.Door"){const auto role=std::get<std::string>(row.fields.at("role"));const bool open=role=="pencil"||(role=="main"?main:service);row.fields["open"]=open;row.fields["unlocked"]=open;}return out;};
 auto route=[&](bool main,bool service,Vec3 spawn,Vec3 target,const char* label){const auto recovery=state(main,service);const auto scene=first_boot_content_scene(recovery,content);const auto& graph=definition.companions.front().routes;GuideController guide(scene,spawn,graph);std::map<std::string,bool> gates;for(const auto& row:recovery.components)if(row.type_id=="firstboot.Door")gates.emplace(row.entity_id,std::get<bool>(row.fields.at("open")));guide.set_doors(gates);bool crossed=false;float minimum_clearance=1000;for(unsigned tick=0;tick<1200;++tick){const auto actual=guide.advance({target,true,scene.revision},1./60);const auto feet=actual.character.feet;crossed=crossed||feet.z>7.5f;if(main){const auto dx=std::max(0.f,std::abs(feet.x+34.5f)-.18f),dz=std::max(0.f,std::abs(feet.z-5.5f)-1.5f);minimum_clearance=std::min(minimum_clearance,std::hypot(dx,dz));}}
 const auto g=guide.state();const auto distance=std::hypot(g.character.feet.x-target.x,g.character.feet.z-target.z);std::cout<<label<<" feet "<<g.character.feet.x<<','<<g.character.feet.y<<','<<g.character.feet.z<<" activity "<<static_cast<int>(g.activity)<<" destination "<<g.destination.x<<','<<g.destination.z<<" target distance "<<distance<<" clearance "<<minimum_clearance<<'\n';return std::tuple{distance,crossed,minimum_clearance,g};};
 const auto [main_distance,main_crossed,main_clear,main_state]=route(true,false,{-33,.03f,1.9f},{-37,.03f,15},"main to Pencil");check(main_distance<2.2f&&main_crossed,"Authored main graph clips opened rotated leaf instead of reaching Pencil");check(main_state.character.grounded&&main_clear>=.245f,"Actual main capsule crossed its rotated open leaf");
 const auto [return_distance,return_crossed,return_clear,return_state]=route(true,false,{-37,.2f,15},{-33,.03f,1.9f},"main return");(void)return_crossed;check(return_distance<2.2f&&return_state.character.grounded&&return_clear>=.245f,"Reverse authored main route clips its open leaf");
 const auto [service_distance,service_crossed,service_clear,service_state]=route(false,true,{-41,.03f,1.9f},{-37,.03f,15},"service to Pencil");(void)service_clear;check(service_distance<2.2f&&service_crossed&&service_state.character.grounded,"Existing service route changed or fails physical capsules");
 const auto [service_return_distance,service_return_crossed,service_return_clear,service_return_state]=route(false,true,{-37,.2f,15},{-41,.03f,1.9f},"service return");(void)service_return_crossed;(void)service_return_clear;check(service_return_distance<2.2f&&service_return_state.character.grounded,"Reverse service route clips Caretaker or open door");
 const auto [closed_distance,closed_crossed,closed_clear,closed_state]=route(false,false,{-33,.03f,1.9f},{-37,.03f,15},"both gates closed");(void)closed_clear;check(closed_distance>10&&!closed_crossed&&closed_state.activity==GuideActivity::blocked,"Closed main/service gates were bypassed");
 check(first_boot_content_encode(content)==first_boot_content_encode(FirstBootContent::create(definition)),"Geometry fixture modified authored content");std::cout<<checks<<" actual capsule graph/door geometry checks pass; CPU collision proof, no gameplay credit\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
